-- ============================================================================
-- COLUMN PARITY - generated by scripts/migration/build-column-parity.mjs
--
-- Target: the NEW project only. NEVER run this on the OLD project.
-- Purpose: add any column that exists in OLD but is missing from the NEW schema,
-- so the import cannot silently drop real values. Types are copied from OLD.
-- Idempotent: every statement is ADD COLUMN IF NOT EXISTS.
-- ============================================================================

set client_min_messages = warning;


-- --------------------------------------------------------------------
-- NOT NULL relaxed for columns OLD never had, on tables that do have rows.
-- The application still supplies these values on every new insert; only the
-- historical rows imported from OLD carry NULL here.
-- --------------------------------------------------------------------

-- employee_tasks.task_month: NOT NULL with no default, but OLD has no such column and 10 row(s) must be imported
alter table public.employee_tasks alter column task_month drop not null;

-- employee_tasks.task_year: NOT NULL with no default, but OLD has no such column and 10 row(s) must be imported
alter table public.employee_tasks alter column task_year drop not null;


-- 0 column(s) added, 2 NOT NULL constraint(s) relaxed.